t = int(input())
arr = []
for i in range(1, 33):
	for j in range(i):
		arr.append((1 << i) + (1 << j))
arr.sort()

def ans(n):
	(low, high) = (0, len(arr))
	(res, diff) = (float('inf'), float('inf'))
	while low <= high:
		mid = (low + high) // 2
		currdiff = abs(n - arr[mid])
		if currdiff < diff:
			diff = currdiff
			res = mid
		if arr[mid] == n:
			return n
		if arr[mid] > n:
			high = mid - 1
		else:
			low = mid + 1
	return arr[res]
for _ in range(t):
	n = int(input())
	print(abs(n - ans(n)))
